<?php
namespace App\Modules\StudentSupport; use App\Modules\Enrollment\Models\Enrollment; use App\Modules\Shared\Audit\AuditRecorder; use App\Modules\StudentSupport\Actions\CreateSupportCaseAction; use App\Modules\StudentSupport\Models\ApprovedSupportSummary; use App\Modules\StudentSupport\Models\SupportAssessment; use App\Modules\StudentSupport\Models\SupportCase; use App\Modules\StudentSupport\Models\SupportObservation; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Gate; use Illuminate\View\View;
class SupportReviewController { public function index():View{Gate::authorize('viewAny',SupportCase::class);return view('support.queue',['cases'=>SupportCase::query()->with('enrollment.student')->latest()->get()]);} public function show(SupportCase $case,Request $request,AuditRecorder $audit):View{Gate::authorize('view',$case);DB::table('support_access_logs')->insert(['support_case_id'=>$case->id,'actor_user_id'=>$request->user()->id,'action'=>'view_raw','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$audit->record($request->user(),'support.case.viewed',$case);return view('support.show',['case'=>$case->load(['enrollment.student','assessments','observations','summaries'])]);} public function create(Enrollment $enrollment,Request $request,CreateSupportCaseAction $create):RedirectResponse{Gate::authorize('create',SupportCase::class);$create->execute($enrollment,$request->user());return back()->with('status','Restricted support case opened.');} public function assessment(SupportCase $case,Request $request):RedirectResponse{Gate::authorize('update',$case);$data=$request->validate(['outcome'=>['required','in:pending,approved,not_approved,more_information_required'],'confidential_rationale'=>['nullable','string','max:5000'],'next_action'=>['nullable','string','max:100']]);SupportAssessment::query()->create(array_merge($data,['support_case_id'=>$case->id,'assessment_type'=>'school_review','completed_on'=>now(),'reviewer_id'=>$request->user()->id]));$case->update(['status'=>$data['outcome']==='pending'?'open':'reviewed','final_outcome'=>$data['outcome']==='approved'?'approved':null]);return back()->with('status','Generic review outcome recorded.');} public function observation(SupportCase $case,Request $request):RedirectResponse{Gate::authorize('update',$case);$data=$request->validate(['body'=>['required','string','max:5000'],'category'=>['nullable','string','max:60']]);SupportObservation::query()->create(array_merge($data,['support_case_id'=>$case->id,'author_id'=>$request->user()->id,'observed_at'=>now()]));return back()->with('status','Restricted observation saved.');} public function summary(SupportCase $case,Request $request):RedirectResponse{Gate::authorize('summary',$case);$data=$request->validate(['summary'=>['required','string','max:3000'],'effective_from'=>['nullable','date'],'effective_until'=>['nullable','date','after_or_equal:effective_from']]);ApprovedSupportSummary::query()->create(array_merge($data,['support_case_id'=>$case->id,'approved_by'=>$request->user()->id,'approved_at'=>now()]));return back()->with('status','Teacher-safe summary approved.');}}
